import java.util.*

object Solution {
    private const val MOD = 1000000007

    @JvmStatic
    fun main() {
        val scanner = Scanner(System.`in`)
        val w = scanner.nextInt()
        val h = scanner.nextInt()

        // 1. Total ordered triples of points
        // N = (w+1)*(h+1)
        val nTotalPoints = (w + 1L) * (h + 1L) % MOD
        // totalOrdered = N * (N-1) * (N-2)
        val totalOrdered = nTotalPoints * ((nTotalPoints - 1 + MOD) % MOD) % MOD * ((nTotalPoints - 2 + MOD) % MOD) % MOD

        // 2. Count ordered collinear triples
        // Horizontal lines: (h+1) lines, each has (w+1) points.
        // Ordered triples per line: (w+1)*w*(w-1)
        var collinearOrdered = (h + 1L) * (w + 1L) % MOD * w % MOD * (w - 1L) % MOD
        // Vertical lines: (w+1) lines, each has (h+1) points.
        // Ordered triples per line: (h+1)*h*(h-1)
        collinearOrdered = (collinearOrdered + (w + 1L) * (h + 1L) % MOD * h % MOD * (h - 1L)) % MOD

        // Diagonal lines with slope != 0, inf.
        // For slope dy/dx where dx > 0, dy > 0, gcd(dx, dy) = 1.
        // Number of points on a segment with this step: k+1 where k = min(w/dx, h/dy).
        // Ordered triples on a line with P points: P*(P-1)*(P-2).
        // Number of such maximal lines?
        // Actually, count segments of length L (L points).
        // For a given primitive vector (dx, dy), number of points in a line segment is k+1.
        // Number of such segments: (w - k*dx + 1) * (h - k*dy + 1).
        // Each segment gives (k+1)*k*(k-1) ordered triples.
        // Since slope can be + or -, multiply by 2.

        for (dx in 1..w) {
            for (dy in 1..h) {
                if (gcd(dx, dy) != 1) continue
                val maxKx = w / dx
                val maxKy = h / dy
                val kMax = minOf(maxKx, maxKy)
                // k is the number of steps. Number of points is k+1.
                // We need k+1 >= 3 => k >= 2.
                for (k in 2..kMax) {
                    val points = k + 1L
                    val triplesOnLine = points * (points - 1) * (points - 2) % MOD
                    val countSegments = (w - k * dx + 1L) * (h - k * dy + 1L) % MOD
                    val contrib = triplesOnLine * countSegments % MOD
                    // Slopes: dy/dx and -dy/dx
                    collinearOrdered = (collinearOrdered + 2 * contrib) % MOD
                }
            }
        }

        // 3. Count ordered non-degenerate triangles with odd double area (half-integer area)
        // Pick's theorem or Shoelace formula.
        // Area = 1/2 | x1(y2-y3) + x2(y3-y1) + x3(y1-y2) |
        // Double Area D = |...|. We need D % 2 == 1 for half-integer area.
        // D = x1y2 + x2y3 + x3y1 - x1y3 - x2y1 - x3y2
        // Mod 2 arithmetic. Coordinates are 0 or 1 mod 2.
        // Types of points: (0,0), (0,1), (1,0), (1,1). Index 0, 1, 2, 3.

        val cntType = LongArray(4)
        // x in [0..w], y in [0..h]
        val evenX = (w / 2) + 1
        val oddX = (w + 1) - evenX
        val evenY = (h / 2) + 1
        val oddY = (h + 1) - evenY

        cntType[0] = evenX * evenY // (0,0)
        cntType[1] = evenX * oddY  // (0,1)
        cntType[2] = oddX * evenY  // (1,0)
        cntType[3] = oddX * oddY   // (1,1)

        var oddDoubleAreaOrdered = 0L
        // Iterate over types of 3 points t1, t2, t3
        for (t1 in 0..3) {
            for (t2 in 0..3) {
                for (t3 in 0..3) {
                    val x1 = t1 / 2; val y1 = t1 % 2
                    val x2 = t2 / 2; val y2 = t2 % 2
                    val x3 = t3 / 2; val y3 = t3 % 2

                    // D = x1(y2-y3) + x2(y3-y1) + x3(y1-y2) mod 2
                    // In mod 2, sub is add.
                    val d = (x1 * (y2 + y3) + x2 * (y3 + y1) + x3 * (y1 + y2)) % 2

                    if (d == 1) {
                        var ways = 1L
                        // Count ordered triples of points with these types
                        // Need to handle cases where types are same/different
                        if (t1 == t2 && t2 == t3) {
                            val c = cntType[t1]
                            ways = c * (c - 1) % MOD * (c - 2) % MOD
                        } else if (t1 == t2) {
                            val c1 = cntType[t1]
                            val c3 = cntType[t3]
                            ways = c1 * (c1 - 1) % MOD * c3 % MOD
                        } else if (t1 == t3) {
                            val c1 = cntType[t1]
                            val c2 = cntType[t2]
                            ways = c1 * (c1 - 1) % MOD * c2 % MOD
                        } else if (t2 == t3) {
                            val c2 = cntType[t2]
                            val c1 = cntType[t1]
                            ways = c2 * (c2 - 1) % MOD * c1 % MOD
                        } else {
                            ways = cntType[t1] * cntType[t2] % MOD * cntType[t3] % MOD
                        }
                        oddDoubleAreaOrdered = (oddDoubleAreaOrdered + ways) % MOD
                    }
                }
            }
        }

        // 4. Result
        // Valid = Total - Collinear - OddDoubleArea
        var ans = (totalOrdered - collinearOrdered) % MOD
        if (ans < 0) ans += MOD
        ans = (ans - oddDoubleAreaOrdered) % MOD
        if (ans < 0) ans += MOD

        println(ans)
    }

    fun gcd(a: Int, b: Int): Int {
        var x = a
        var y = b
        while (y != 0) {
            val temp = y
            y = x % y
            x = temp
        }
        return x
    }
}
